  "Quando l'ufficio ti affida un mezzo, lo trovi qui con i suoi documenti. Per un attrezzo con l'etichetta QR, tocca «Scansiona».": "Kur zyra të beson një mjet, e gjen këtu me dokumentet e tij. Për një vegël me etiketë QR, prek «Skano».",
  "Quando prendi materiale dall’Inventario, la richiesta compare qui con la risposta del magazzino.": "Kur merr material nga Inventari, kërkesa shfaqet këtu me përgjigjen e magazinës.",
