  "Il giornaliero lo invia il responsabile: tu registra entrata e uscita. Puoi aggiungere foto dal cantiere.": "Raportin ditor e dërgon përgjegjësi: ti regjistro hyrjen dhe daljen. Mund të shtosh foto nga kantieri.",
  "Descrivi i lavori che il cliente deve confermare prima di raccogliere la firma.": "Përshkruaj punët që klienti duhet të konfirmojë para se të marrësh firmën.",
  "Per il collaudo servono nome e cognome del cliente e la sua firma.": "Për kolaudimin duhen emri dhe mbiemri i klientit dhe firma e tij.",
  "Compila: {campi}": "Plotëso: {campi}",
  "Esiste già un rapportino per questo cantiere e questa giornata. Per correggerlo contatta l’ufficio.": "Ekziston tashmë një raport për këtë kantier dhe këtë ditë. Për ta korrigjuar kontakto zyrën.",
