  "Straordinario · facoltativo": "Orë shtesë · opsionale",
  "Sono ore aggiuntive: se incluse nelle ore rilevate, sottraile dalle ordinarie qui sopra.": "Janë orë shtesë: nëse janë përfshirë te orët e regjistruara, zbriti nga orët e rregullta më sipër.",
