  "Ogni utente collega il proprio Gmail o Outlook. Vedi solo le tue connessioni; le email di altri membri del team non sono visibili.": "Çdo përdorues lidh Gmail-in ose Outlook-un e vet. Sheh vetëm lidhjet e tua; email-et e anëtarëve të tjerë të ekipit nuk janë të dukshme.",
