  "Prima della firma prepara il verbale con verifiche, esito ed eventuali riserve. La richiesta collegata al solo ordine non contiene un documento da firmare.": "Para firmës përgatit procesverbalin me kontrollet, rezultatin dhe rezervat e mundshme. Kërkesa e lidhur vetëm me porosinë nuk përmban një dokument për t'u firmosur.",
