  "Chi ha lavorato oggi?": "Kush ka punuar sot?",
  "Chi ha lavorato in questa giornata?": "Kush ka punuar këtë ditë?",
  "Le ore sono quelle timbrate in cantiere: controllale e correggile se serve. Chi non ha timbrato lo aggiungi tu, con le sue ore.": "Orët janë ato të regjistruara në kantier: kontrolloji dhe korrigjoji nëse duhet. Kush nuk ka regjistruar orarin, e shton ti me orët e tij.",
  "Tocca chi era in cantiere e scrivi le sue ore. Chi ha già mandato il suo rapportino non va segnato di nuovo.": "Prek kush ishte në kantier dhe shkruaji orët. Kush e ka dërguar tashmë raportin e vet nuk duhet shënuar sërish.",
  "Tocca chi della tua squadra era in cantiere e scrivi le sue ore. Chi ha già mandato il suo rapportino non va segnato di nuovo.": "Prek kush nga ekipi yt ishte në kantier dhe shkruaji orët. Kush e ka dërguar tashmë raportin e vet nuk duhet shënuar sërish.",
  "ha mandato il suo": "e ka dërguar raportin e vet",
  "già registrato da un collega": "regjistruar tashmë nga një koleg",
  "Ha timbrato {timbrate}: hai scritto più di {scarto}.": "Ka regjistruar {timbrate}: ke shkruar mbi {scarto} më shumë.",
  "Ha timbrato {timbrate}: hai scritto meno di {scarto}.": "Ka regjistruar {timbrate}: ke shkruar mbi {scarto} më pak.",
  "Su cosa hai lavorato oggi?": "Në çfarë ke punuar sot?",
  "Su cosa hai lavorato in questa giornata?": "Në çfarë ke punuar këtë ditë?",
  "Ruolo Campo non ancora verificato. Puoi indicare le fasi lavorate; la modifica delle percentuali resta disabilitata.": "Roli në kantier nuk është verifikuar ende. Mund të tregosh fazat e punuara; ndryshimi i përqindjeve mbetet i çaktivizuar.",
  "Tocca le fasi e indica l'avanzamento raggiunto (facoltativo)": "Prek fazat dhe trego ecurinë e arritur (opsionale)",
  "Tocca le fasi su cui hai lavorato: servono ad attribuire le tue ore. L'avanzamento lo dichiara il capocantiere.": "Prek fazat në të cilat ke punuar: shërbejnë për t'ua caktuar orët e tua. Ecurinë e deklaron përgjegjësi i kantierit.",
