  "Persone collegate adesso, tentativi di accesso e azioni sugli utenti": "Personat e lidhur tani, tentativat e hyrjes dhe veprimet mbi përdoruesit",
  "I tuoi consensi, la copia dei tuoi dati e la richiesta di cancellazione": "Pëlqimet e tua, kopja e të dhënave të tua dhe kërkesa për fshirje",
